fn nanargmax(a: Vec<i8>) -> usize {
    // Since the array is guaranteed to be non-empty, we can safely initialize
    // the maximum value and its index to the first element.
    let mut max_idx = 0;
    let mut max_val = a[0];

    // Iterate through the rest of the elements, updating the index whenever
    // we find a strictly greater value.
    for (i, &v) in a.iter().enumerate().skip(1) {
        if v > max_val {
            max_val = v;
            max_idx = i;
        }
    }

    max_idx
}

